style.css:
@-moz-document regexp("https?://(www\.)?youtube\.com/.*") {
:root {
    --yt-player-bg: #0b0d0f;
    --yt-bg: #070708;
    --yt-text: #e8eef1;
    --yt-muted: #9aa3a8;
    --yt-accent: #ff444f;
  }

  /* page bg & text */
  ytd-app, ytd-watch-flexy, html, body {
    background: var(--yt-bg) !important;
    color: var(--yt-text) !important;
  }

  /* main player area */
  #player, .html5-video-player, #player-theater-container {
    background: linear-gradient(180deg, var(--yt-player-bg), #060607) !important;
  }

  /* header & search bar */
  #masthead-container, #container.ytd-masthead {
    background: rgba(10,10,11,0.85) !important;
    backdrop-filter: blur(6px);
  }

  /* text colors */
  yt-formatted-string, .title, #video-title, .ytd-rich-grid-media .title {
    color: var(--yt-text) !important;
  }
  #secondary-inner {
    background: transparent !important;
  }

  /* links / accent */
  a, a:visited, #subscribe-button, ytd-toggle-button-renderer tp-yt-paper-button {
    color: var(--yt-accent) !important;
  }

  /* muted text */
  .yt-simple-endpoint[href], .metadata, .style-scope.ytd-video-secondary-info-renderer {
    color: var(--yt-muted) !important;
  }
}
